from pathlib import Path
import re,json,difflib,html
P=Path(__file__).parent
script=P.joinpath('narration.txt').read_text(); words=script.split(); asr=json.loads(P.joinpath('assets/transcript.json').read_text())
norm=lambda s: re.sub(r'[^a-z0-9]','',s.lower())
a=[norm(w) for w in words];b=[norm(w['text']) for w in asr]; mapping={}
sm=difflib.SequenceMatcher(None,a,b,autojunk=False)
for tag,i,j,k,l in sm.get_opcodes():
 if tag=='equal':
  for n in range(j-i):mapping[i+n]=(asr[k+n]['start'],asr[k+n]['end'])
 else:
  for n in range(i,j):
   start=asr[min(k,len(asr)-1)]['start'];end=asr[min(max(k,l-1),len(asr)-1)]['end'];mapping[n]=(start+(end-start)*(n-i)/max(1,j-i),start+(end-start)*(n-i+1)/max(1,j-i))
print('Alignment:',sm.ratio(), 'differences:',[(tag,words[i:j],[w['text'] for w in asr[k:l]]) for tag,i,j,k,l in sm.get_opcodes() if tag!='equal'])
offset=.7; paragraphs=script.split('\n\n'); starts=[];idx=0
for para in paragraphs:starts.append(round(mapping[idx][0]+offset,3));idx+=len(para.split())
starts[0]=0; end=198
# readable phrase captions split at punctuation or 85 characters
caps=[];buf=[];starti=0
for i,w in enumerate(words):
 if not buf:starti=i
 buf.append(w)
 if re.search(r'[.!?;:]$',w) or len(' '.join(buf))>=78 or i==len(words)-1:
  caps.append({'start':round(mapping[starti][0]+offset,3),'end':round(mapping[i][1]+offset+.12,3),'text':' '.join(buf)});buf=[]
for i in range(len(caps)-1):caps[i]['end']=min(caps[i]['end'],caps[i+1]['start']-.015)
P.joinpath('captions.json').write_text(json.dumps(caps,indent=2));P.joinpath('scene-timing.json').write_text(json.dumps(starts))
def tc(t):
 ms=round(t*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
P.joinpath('captions.srt').write_text('\n\n'.join(f'{i+1}\n{tc(c["start"])} --> {tc(c["end"])}\n{c["text"]}' for i,c in enumerate(caps))+'\n')
def E(s):return html.escape(s)
def shot(file,style='',cl=''):
 return f'<div class="shot {cl}"><img data-layout-allow-overflow src="assets/{file}" style="{style}" alt="Actual SecondLook product capture"></div>'
def head(k,title,sub=''):
 return f'<div class="eyebrow">{k}</div><h1>{title}</h1>'+ (f'<p class="sub">{sub}</p>' if sub else '')
def card(title,text):return f'<div class="card"><h2>{title}</h2><p>{text}</p></div>'
